#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <cmath>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long q;
    cin >> n >> q;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    vector<vector<long long>> qs(q, vector<long long>(2));
    for (int i = 0; i < q; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> qs[i][j];
        }
    }

    vector<long long> vals(a.begin(), a.end());
    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());
    vector<int> rk(n);
    for (long long i = 0; i < n; i++) rk[i] = (int)(lower_bound(vals.begin(), vals.end(), a[i]) - vals.begin());
    vector<long long> cnt(vals.size(), 0);
    long long block = max(1LL, (long long)(n / sqrt((double)q)));
    vector<int> order(q);
    for (long long j = 0; j < q; j++) order[j] = (int)j;
    sort(order.begin(), order.end(), [&](int x, int y) {
        long long bx = qs[x][0] / block, by = qs[y][0] / block;
        if (bx != by) return bx < by;
        if (bx % 2 == 0) return qs[x][1] < qs[y][1];
        return qs[x][1] > qs[y][1];
    });
    vector<long long> ans(q, 0);
    long long cl = 0, cr = -1, cur = 0;
    for (long long idx = 0; idx < q; idx++) {
        int j = order[idx];
        long long l = qs[j][0] - 1, rr = qs[j][1] - 1;
        while (cl > l) {
            cl--;
            int v = rk[cl];
            cur += cnt[v];
            cnt[v]++;
        }
        while (cr < rr) {
            cr++;
            int v = rk[cr];
            cur += cnt[v];
            cnt[v]++;
        }
        while (cl < l) {
            int v = rk[cl];
            cnt[v]--;
            cur -= cnt[v];
            cl++;
        }
        while (cr > rr) {
            int v = rk[cr];
            cnt[v]--;
            cur -= cnt[v];
            cr--;
        }
        ans[j] = cur;
    }
    string out;
    for (long long j = 0; j < q; j++) {
        if (j > 0) out += " ";
        out += to_string(ans[j]);
    }
    cout << out << "\n";

    return 0;
}

