import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long q = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());
        long[][] qs = new long[(int) q][2];
        for (int i = 0; i < qs.length; i++) {
            for (int j = 0; j < qs[i].length; j++) {
                qs[i][j] = Long.parseLong(next());
            }
        }

        int cnt0 = (int) n;
        int qq = (int) q;
        long[] keys = new long[cnt0];
        for (int i = 0; i < cnt0; i++) keys[i] = (a[i] << 15) | i;
        Arrays.sort(keys);
        int[] rk = new int[cnt0];
        int m = 0;
        long last = -1;
        for (int i = 0; i < cnt0; i++) {
            long v = keys[i] >> 15;
            if (v != last) {
                m++;
                last = v;
            }
            rk[(int) (keys[i] & 32767)] = m - 1;
        }
        long[] cnt = new long[m];
        int block = Math.max(1, (int) (n / Math.sqrt(q)));
        long[] ks = new long[qq];
        for (int j = 0; j < qq; j++) {
            long bi = qs[j][0] / block;
            long rr = (bi % 2 == 0) ? qs[j][1] : 32767 - qs[j][1];
            ks[j] = (bi << 30) | (rr << 15) | j;
        }
        Arrays.sort(ks);
        long[] ans = new long[qq];
        int cl = 0, cr = -1;
        long cur = 0;
        for (int idx = 0; idx < qq; idx++) {
            int j = (int) (ks[idx] & 32767);
            int l = (int) qs[j][0] - 1, rr = (int) qs[j][1] - 1;
            while (cl > l) {
                cl--;
                int v = rk[cl];
                cur += cnt[v];
                cnt[v]++;
            }
            while (cr < rr) {
                cr++;
                int v = rk[cr];
                cur += cnt[v];
                cnt[v]++;
            }
            while (cl < l) {
                int v = rk[cl];
                cnt[v]--;
                cur -= cnt[v];
                cl++;
            }
            while (cr > rr) {
                int v = rk[cr];
                cnt[v]--;
                cur -= cnt[v];
                cr--;
            }
            ans[j] = cur;
        }
        StringBuilder out = new StringBuilder();
        for (int j = 0; j < qq; j++) {
            if (j > 0) out.append(" ");
            out.append(ans[j]);
        }
        System.out.println(out);
    }
}
